code.java:
class Solution {
    public int sumOfSquares(int[] nums){
        int answer=0,n=nums.length;
        for(int i=0;i<n;i++)if(n%(i+1)==0)answer+=nums[i]*nums[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun sumOfSquares(nums:IntArray):Int{
        var answer=0;
        for(i in nums.indices)if(nums.size%(i+1)==0)answer+=nums[i]*nums[i];
        return answer
    }
}

code.cpp:
class Solution {
    public:int sumOfSquares(vector<int>& nums){
